export const createManualOrderBodyDiscountExplanationMax = 500;

export const createManualOrderBodyCustomerFirstNameMax = 300;

export const createManualOrderBodyCustomerLastNameMax = 300;

export const createManualOrderBodyCustomerDisplayNameMax = 300;

export const createManualOrderBodyCustomerEmailMax = 300;

export const createManualOrderBodyCustomerPhoneMax = 100;

export const createManualOrderBodyRecipientOneFirstNameMax = 300;

export const createManualOrderBodyRecipientOneLastNameMax = 300;

export const createManualOrderBodyRecipientOneDisplayNameMax = 300;

