export const CreateManualOrderBody = zod.object({
  "source": zod.string().max(createManualOrderBodySourceMax).nullish().describe('Order source; defaults to `manual` when omitted.'),
  "status": zod.union([zod.literal('pending'),zod.literal('processing'),zod.literal('preparing'),zod.literal('ready_for_delivery'),zod.literal('out_for_delivery'),zod.literal('completed'),zod.literal('cancelled'),zod.literal('on_hold'),zod.literal('refunded'),zod.literal(null)]).nullish(),
  "ordered_at": zod.coerce.date().nullish(),
  "delivery_type": zod.string().max(createManualOrderBodyDeliveryTypeMax).nullish(),
  "delivery_address": zod.record(zod.string(), zod.unknown()).nullish().describe('Free-form delivery address object stored as jsonb.'),
  "delivery_instructions": zod.string().max(createManualOrderBodyDeliveryInstructionsMax).nullish(),
  "window_start": zod.coerce.date().nullish(),
  "window_end": zod.coerce.date().nullish(),
  "card_message": zod.string().max(createManualOrderBodyCardMessageMax).nullish(),
  "card_from": zod.string().max(createManualOrderBodyCardFromMax).nullish(),
  "card_to": zod.string().max(createManualOrderBodyCardToMax).nullish(),
  "totals": zod.record(zod.string(), zod.unknown()).nullish().describe('Displayed totals. For manual orders the server recomputes subtotal, shipping, currency, and total from line items and the selected delivery city.'),
  "discount": zod.object({
  "type": zod.enum(['percent', 'amount']),
  "value": zod.number().gt(createManualOrderBodyDiscountValueExclusiveMin),
  "reason": zod.string().min(1).max(createManualOrderBodyDiscountReasonMax),
  "explanation": zod.string().max(createManualOrderBodyDiscountExplanationMax).nullish()
}).nullish().describe('CMC POS order-level discount. Only accepted for `source: cmc-pos`; the API calculates its amount from line items and requires the `cmc_pos.discount` permission.\n'),
  "customer": zod.object({
  "contact_id": zod.string().uuid().nullish().describe('Links an existing contact by id (from wizard search) instead of upserting by fields. Must belong to the caller\'s workspace; other fields are optional overrides when set.\n'),
  "first_name": zod.string().max(createManualOrderBodyCustomerFirstNameMax).nullish(),
  "last_name": zod.string().max(createManualOrderBodyCustomerLastNameMax).nullish(),
  "display_name": zod.string().max(createManualOrderBodyCustomerDisplayNameMax).nullish(),
  "email": zod.string().max(createManualOrderBodyCustomerEmailMax).nullish(),
  "phone": zod.string().max(createManualOrderBodyCustomerPhoneMax).nullish()
}).describe('Customer or recipient details for a manual order. Resolved against the shared contact pool.'),
  "recipient": zod.union([zod.object({
  "contact_id": zod.string().uuid().nullish().describe('Links an existing contact by id (from wizard search) instead of upserting by fields. Must belong to the caller\'s workspace; other fields are optional overrides when set.\n'),
  "first_name": zod.string().max(createManualOrderBodyRecipientOneFirstNameMax).nullish(),
  "last_name": zod.string().max(createManualOrderBodyRecipientOneLastNameMax).nullish(),
  "display_name": zod.string().max(createManualOrderBodyRecipientOneDisplayNameMax).nullish(),
  "email": zod.string().max(createManualOrderBodyRecipientOneEmailMax).nullish(),
  "phone": zod.string().max(createManualOrderBodyRecipientOnePhoneMax).nullish()
}).describe('Customer or recipient details for a manual order. Resolved against the shared contact pool.'),zod.null()]).optional(),
  "line_items": zod.array(zod.object({
  "product_id": zod.number().nullish().describe('Catalog product id, when the line was added from the product picker.'),
  "external_id": zod.string().max(createManualOrderBodyLineItemsItemExternalIdMax).nullish(),
  "sku": zod.string().max(createManualOrderBodyLineItemsItemSkuMax).nullish(),
  "name": zod.string().min(1).max(createManualOrderBodyLineItemsItemNameMax),
  "quantity": zod.number().gt(createManualOrderBodyLineItemsItemQuantityExclusiveMin).max(createManualOrderBodyLineItemsItemQuantityMax),
  "unit_price": zod.number().min(createManualOrderBodyLineItemsItemUnitPriceMin).nullish(),
  "image_url": zod.string().max(createManualOrderBodyLineItemsItemImageUrlMax).nullish(),
  "custom_input": zod.string().max(createManualOrderBodyLineItemsItemCustomInputMax).nullish().describe('Per-line personalization; truncated to 22 chars on persist.')
})).max(createManualOrderBodyLineItemsMax),
  "payment_link_id": zod.number().nullish().describe('ID of an existing payment link to associate with this order. When supplied and the link is paid, payment method is set to `payment_link` and status to `paid`.'),
  "collect_address": zod.boolean().nullish().describe('When true, creates an address-collection request for the recipient after the order is saved (Address Collector wizard toggle).'),
  "preferred_language": zod.string().max(createManualOrderBodyPreferredLanguageMax).nullish().describe('Recipient\'s preferred outreach language for address collection (e.g. \'en\' or \'ar\').'),
  "idempotency_key": zod.string().min(1).max(createManualOrderBodyIdempotencyKeyMax).nullish().describe('Client-generated retry key for a CMC POS custom order.'),
  "payment": zod.object({
  "status": zod.string().max(createManualOrderBodyPaymentStatusMax).nullish(),
  "method": zod.string().max(createManualOrderBodyPaymentMethodMax).nullish(),
  "currency": zod.string().max(createManualOrderBodyPaymentCurrencyMax).nullish()
}).nullish(),
  "notes": zod.object({
  "customer_note": zod.string().max(createManualOrderBodyNotesCustomerNoteMax).nullish(),
  "florist_note": zod.string().max(createManualOrderBodyNotesFloristNoteMax).nullish(),
  "driver_note": zod.string().max(createManualOrderBodyNotesDriverNoteMax).nullish(),
  "internal_note": zod.string().max(createManualOrderBodyNotesInternalNoteMax).nullish()
}).nullish()
}).describe('Payload for the dashboard Create Order wizard. At least one line item and customer details are required. Payment records the method + status only; no card is charged and no payment link is generated.\n')


