/**
 * Auto-detects the payload format from the Content-Type header and handles Postmark (JSON), Mailgun (multipart/form-data), and SendGrid inbound parse (multipart/form-data). Each PDF attachment found in the email is stored and queued for extraction through the same pipeline as the direct PDF webhook.
The workspace owner is identified from the recipient (To) address using the format `marketplace-reports+{workspaceOwnerId}@<inbound-domain>`.
Authenticated via `x-marketplace-secret` (or `x-webhook-secret`) header.
**Format detection:** - `Content-Type: application/json` → Postmark (base64 attachments in `Attachments[]`) - `Content-Type: multipart/form-data` with `envelope` field → SendGrid inbound parse - `Content-Type: multipart/form-data` without `envelope` field → Mailgun inbound routing
**Setup (Postmark):** 1. Create an Inbound Domain (e.g. inbound.presentail.com). 2. Point the domain's MX record to Postmark's inbound MX servers. 3. Set the Inbound Webhook URL to `POST /api/webhooks/marketplace-email/inbound`
   with the `x-marketplace-secret` custom header.
4. Give each workspace owner a dedicated To address:
   `marketplace-reports+{workspaceOwnerId}@inbound.presentail.com`.

**Setup (Mailgun):** 1. Enable Mailgun Inbound Routing and forward to this endpoint. 2. Pass `x-marketplace-secret` as a custom header. 3. Mailgun posts multipart/form-data with file fields `attachment-1`, `attachment-2`, …
   and a `recipient` text field for the To address.

**Setup (SendGrid):** 1. Enable SendGrid Inbound Parse Webhook pointing at this endpoint. 2. Pass `x-marketplace-secret` via a custom header or allowlist by IP. 3. SendGrid posts multipart/form-data with file fields `attachment1`, `attachment2`, …
   and an `envelope` JSON field containing `{ "to": [...], "from": "..." }`.

 * @summary Inbound email webhook for marketplace PDF reports
 */
export const MarketplaceEmailInboundBody = zod.object({
  "MessageID": zod.string().optional().describe('Unique message ID for deduplication.'),
  "From": zod.string().optional(),
  "To": zod.string().optional().describe('Recipient address. Must contain the workspace owner ID using the plus-addressing format: `marketplace-reports+{workspaceOwnerId}@<domain>`.\n'),
  "ToFull": zod.array(zod.object({
  "Email": zod.string().optional(),
  "Name": zod.string().optional()
})).optional(),
  "Subject": zod.string().optional(),
  "Attachments": zod.array(zod.object({
  "Name": zod.string(),
  "Content": zod.string().describe('Base64-encoded file content.'),
  "ContentType": zod.string(),
  "ContentLength": zod.number().optional()
})).optional(),
  "workspace_owner_id": zod.string().optional().describe('Explicit workspace owner ID. Takes precedence over the To-address parsing if provided.\n')
}).describe('Postmark inbound email JSON payload.')

export const MarketplaceEmailInboundResponse = zod.object({
  "success": zod.boolean(),
  "message": zod.string().optional(),
  "imports": zod.array(zod.unknown()).optional()
})


